// Keep these file types
const exts = ['pdf','png','jpg','jpeg','docx','xlsx','csv','zip'];
const out = [];
for (const item of $input.all()) {
  const from = (item.json.from?.value?.[0]?.address || 'unknown').replace(/[^\w.@+-]/g, '_');
  const month = new Date(item.json.date || Date.now()).toISOString().slice(0, 7);
  for (const [key, bin] of Object.entries(item.binary || {})) {
    const name = (bin.fileName || key).replace(/[^\w.@+-]+/g, '_');
    if (!exts.includes(name.split('.').pop().toLowerCase())) continue;
    // n8n 2.x only writes inside ~/.n8n-files and doesn't create sub-folders, so the folder structure goes into the file name
    out.push({ json: { path: `/home/node/.n8n-files/attachments/${month}__${from}__${name}` }, binary: { data: bin } });
  }
}
return out;
